def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    sep_color = g[0][0]

    horizontal = next((r for r in range(1, h)
                       if len(set(g[r])) == 1 and g[r][0] == sep_color), None)
    if horizontal is not None:
        sep = horizontal
        short_bg = next(x for x in g[1] if x != sep_color)
        long_bg = g[sep + 1][0]
        a = next(r for r in range(sep)
                 if any(x not in (short_bg, sep_color) for x in g[r]))
        b = next(r for r in range(sep + 1, h) if any(x != long_bg for x in g[r]))
        for c in range(w):
            x, y = g[a][c], g[b][c]
            x_mark = x not in (short_bg, sep_color)
            y_mark = y != long_bg
            if y_mark:
                g[b][c] = long_bg
                if x_mark and x == y:
                    g[sep + 1][c] = x
                else:
                    g[h - 1][c] = y
        return g

    sep = next(c for c in range(1, w)
               if all(g[r][c] == sep_color for r in range(h)))
    left_bg = next(x for x in g[1][:sep] if x != sep_color)
    right_bg = g[1][sep + 1]
    a = next(c for c in range(sep)
             if any(g[r][c] not in (left_bg, sep_color) for r in range(h)))
    b = next(c for c in range(sep + 1, w) if any(g[r][c] != right_bg for r in range(h)))
    for r in range(h):
        x, y = g[r][a], g[r][b]
        x_mark = x not in (left_bg, sep_color)
        y_mark = y != right_bg
        if y_mark:
            g[r][b] = right_bg
            if x_mark and x == y:
                g[r][sep + 1] = x
            else:
                g[r][w - 1] = y
    return g
